// First-party TrueType probe: only U+6C49, a triangle with a two-em advance.
// Generated by scripts/generate-word-font-probe.py. It is never used for
// document text or serialized into the document package.
const probeBytes = "";
const probes = new WeakMap<Document, { family: string; ready: Promise<void> }>();
let serial = 0;

/** An explicit final fallback distinguishes a face's own Han glyph from the
 * platform's implicit fallback, whose fontBoundingBox can match the Latin face. */
export function loadWordFontProbe(document: Document): Promise<void> {
  const known = probes.get(document);
  if (known) return known.ready;
  const family = "Doffi Metric Probe " + ++serial,
    bytes = Uint8Array.from(atob(probeBytes), character => character.charCodeAt(0)),
    face = new document.defaultView!.FontFace(family, bytes);
  const ready = face.load().then(() => { document.fonts.add(face); });
  probes.set(document, { family, ready });
  return ready;
}

export function wordFontHasHan(document: Document, context: CanvasRenderingContext2D,
  css: CSSStyleDeclaration): boolean {
  const family = probes.get(document)?.family;
  if (!family) return false;
  const names = (css.fontFamily.match(/"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|[^,]+/g) ?? [])
    .filter(name => !/^(?:serif|sans-serif|monospace|cursive|fantasy|system-ui|ui-serif|ui-sans-serif|ui-monospace|ui-rounded|emoji|math|fangsong)$/i.test(name.trim()));
  if (!names.length) return false;
  context.font = `${css.fontStyle} ${css.fontWeight} 100px ${names.join(",")},"${family}"`;
  return Math.abs(context.measureText("汉").width - 200) > 0.01;
}
